'use server';

import { cookies } from 'next/headers';
import { refresh } from 'next/cache';

const NOTIFICATION_COOKIE = 'notifications-enabled';

export async function toggleNotificationPreference() {
  const cookieStore = await cookies();
  const current = cookieStore.get(NOTIFICATION_COOKIE)?.value === 'true';
  const next = !current;

  cookieStore.set(NOTIFICATION_COOKIE, String(next), {
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 365, // 1 year
  });

  refresh();
}

export async function getNotificationPreference(): Promise<boolean> {
  const cookieStore = await cookies();
  return cookieStore.get(NOTIFICATION_COOKIE)?.value === 'true';
}

