'use client';

import { toggleNotificationPreference } from './actions';
import { useTransition } from 'react';

export function NotificationToggle({ enabled }: { enabled: boolean }) {
  const [isPending, startTransition] = useTransition();

  return (
    <div>
      <label className="flex items-center gap-2 cursor-pointer">
        <span>Email notifications</span>
        <button
          type="button"
          onClick={() => {
            startTransition(async () => {
              await toggleNotificationPreference();
            });
          }}
          disabled={isPending}
          className={`
            relative w-11 h-6 rounded-full cursor-pointer transition-colors
            ${enabled ? 'bg-blue-600' : 'bg-gray-300'}
            ${isPending ? 'opacity-70' : ''}
          `}
          role="switch"
          aria-checked={enabled}
          aria-label="Toggle notifications"
        >
          <span
            className={`
              absolute top-1 w-4 h-4 rounded-full bg-white transition-transform
              ${enabled ? 'left-6 translate-x-0' : 'left-1'}
            `}
          />
        </button>
        {isPending && <span className="text-sm text-gray-500">Updating...</span>}
      </label>
      <p className="mt-2 text-sm text-gray-600">
        Notifications are {enabled ? 'on' : 'off'}
      </p>
    </div>
  );
}

