'use client';

import { toggleNotificationPreference } from './actions';
import { useTransition } from 'react';

export function NotificationToggle({ enabled }: { enabled: boolean }) {
  const [isPending, startTransition] = useTransition();

  return (
    <div style={{ marginTop: '1rem' }}>
      <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer' }}>
        <span>Email notifications</span>
        <button
          type="button"
          onClick={() => {
            startTransition(async () => {
              await toggleNotificationPreference();
            });
          }}
          disabled={isPending}
          style={{
            position: 'relative',
            width: 44,
            height: 24,
            borderRadius: 12,
            cursor: isPending ? 'not-allowed' : 'pointer',
            backgroundColor: enabled ? '#2563eb' : '#d1d5db',
            opacity: isPending ? 0.7 : 1,
            border: 'none',
            padding: 0,
          }}
          role="switch"
          aria-checked={enabled}
          aria-label="Toggle notifications"
        >
          <span
            style={{
              position: 'absolute',
              top: 4,
              left: enabled ? 24 : 4,
              width: 16,
              height: 16,
              borderRadius: '50%',
              backgroundColor: 'white',
              transition: 'left 0.2s ease',
            }}
          />
        </button>
        {isPending && <span style={{ fontSize: '0.875rem', color: '#6b7280' }}>Updating...</span>}
      </label>
      <p style={{ marginTop: '0.5rem', fontSize: '0.875rem', color: '#4b5563' }}>
        Notifications are {enabled ? 'on' : 'off'}
      </p>
    </div>
  );
}

